uhCkkRW9vLoJMUkcRNPv_KQj2_u3CSly7mg7gxX8.description:
{
  "outcome": "Any node — leaf, mid-level, or root — carries completion criteria, and a node's achievement is the consequence of those criteria being met (an executable check, a human stamp, or an LLM judgement), not a bare flag set by hand. At a branch the criteria act as integration tests over its children, so achievement at every level is bounded in reality, not merely propagated up from the bottom.",
  "handle": "completion"
}

uhCkkb-ZEjyXus5ArOiHUoN-99Kcw4t1m4JLntQU.description:
{
  "outcome": "Each completion criterion records who or what judges it — a human with a stamp, an executable check, or an LLM — so anyone reading the node knows exactly how it will be verified. Executable criteria are the ones an agent can run unattended.",
  "spec": "fields.completionCriteria = list of {statement, evaluator ∈ {human, executable, llm}, evidence?}. Executable criteria carry enough detail (command or url + expected result) to run without a human.",
  "completionCriteria": [
    {
      "statement": "An agent reads a leaf's executable criterion, runs it, and reports pass/fail with captured evidence",
      "evaluator": "executable"
    },
    {
      "statement": "A human-evaluator criterion presents a stamp/approve affordance",
      "evaluator": "human"
    }
  ]
}

uhCkkcUXleDqZWKVCOnChpK37Sl3f4TSaFBBeQ1_.description:
{
  "outcome": "A leaf is Achieved because a completion criterion was met — an executable check passed, a human stamped a manual-review criterion, or an LLM judged it — and the achievement is the recorded consequence of that evaluation, carrying its evidence. The old bare 'achieved' flag, set by hand with nothing behind it, is replaced: marking a leaf done means satisfying at least one criterion, so achievement is bounded in reality rather than asserted.",
  "spec": "Achievement is derived: status becomes Achieved only when >=1 completion criterion is met, and stores a reference to the grounding criterion plus its evidence. A human stamp is the human-evaluator path of a criterion, not a separate flag.",
  "completionCriteria": [
    {
      "statement": "A leaf with no met completion criterion cannot be shown Achieved",
      "evaluator": "executable"
    }
  ]
}

uhCkkM9ErS_No-ivBy2Yanm0zZz-koWRc8tCnhgt.description:
{
  "outcome": "A Small's task list is its working breakdown — the path to completion, maintained like a todo list and checked off as the work lands. Achievement is not an independent flag: a Small reaches Achieved only when its tasks are all checked and its completion criteria are met. Tasks are the path, completion criteria are the proof, achievement is the result of both.",
  "spec": "Couple the three facets: taskList (the breakdown), completionCriteria (the proof), and achievementStatus (the result). A Small becomes Achieved when all its tasks are complete AND its criteria pass — derived from those inputs rather than set directly (ties to b4 and the computed results in b6).",
  "completionCriteria": [
    {
      "statement": "A Small with unchecked tasks or an unmet criterion cannot be shown Achieved",
      "evaluator": "executable"
    },
    {
      "statement": "Checking the last task and meeting the criteria flips the Small to Achieved with no separate toggle",
      "evaluator": "human"
    }
  ]
}

uhCkkPYG5MQb8WXScoQ3VUXKtzegvaLFOqbp3WnW.description:
{
  "outcome": "A branch node is not Achieved merely because all its children are. It carries its own completion criteria — integration tests over the children's combined result — that must also pass. Achievement at a branch is bounded in reality by these integration criteria in addition to upward propagation, catching the case where every child is individually done but the assembled whole does not yet work.",
  "spec": "Computed achievement at a branch = (all children achieved) AND (the branch's own completion criteria pass). Integration criteria are ordinary completion criteria authored at the branch, usually executable.",
  "completionCriteria": [
    {
      "statement": "A branch with all children achieved but a failing integration criterion is not shown achieved",
      "evaluator": "executable"
    }
  ]
}

uhCkkuBpw0etNXsTr1Y47saOYDGzmDH33dbjrU21.description:
{
  "outcome": "Executable completion criteria are re-run as the work evolves, so an outcome once achieved stays provably intact. When a later change breaks a previously-passing criterion, its node surfaces red. Invariance is not a separate declaration — it is the standing guarantee the re-run completion tests provide.",
  "completionCriteria": [
    {
      "statement": "A previously-passing executable criterion fails after a breaking change and its node surfaces red up the branch",
      "evaluator": "executable"
    },
    {
      "statement": "Re-running all criteria after an unrelated change leaves green nodes green",
      "evaluator": "executable"
    }
  ]
}

